import sys
import re
import requests
from ctypes import CDLL, c_char_p, byref, create_string_buffer
import nltk
from textblob import TextBlob

# Load C DNS resolution library
dll = CDLL('path/to/your/libdnsresolver.so')
dns_resolve = dll.dns_resolve
dns_resolve.argtypes = [c_char_p]
dns_resolve.restype = c_char_p

# Function to resolve IP address from URL
def resolve_ip(url):
    hostname = url.split("":"")[0].split(""/"")[-1]
    ip = create_string_buffer(8 * 4)
    dns_resolve(hostname.encode('utf-8'), byref(ip))
    return ip.value.decode()

# Read URLs from input file
with open(sys.argv[1], 'r') as f:
    urls = set(re.findall(r'http[s]?://(?:www\.)?(?:[a-zA-Z]|[0-9]|[$-_@.&+]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', f.read()))

# Store sentiment scores for each page dynamically
sentiments = {}

for url in urls:
    try:
        response = requests.get(url)
        if response.status_code == 200:
            content = response.text
            analysis = TextBlob(content)
            sentiment_score = analysis.sentiment.polarity
            ip = resolve_ip(url)
            sentiments[ip] = (sentiment_score, analysis.sentiment.subjectivity)
    except Exception as e:
        print(f""Error fetching content from {url}: {e}"")

# Organize data according to user preference and write into output file
with open(sys.argv[2], 'w') as f:
    if sys.argv[3] == ""positive"":
        positive = {k: v for k, v in sentiments.items() if v[0] > 0}
        negative = {k: v for k, v in sentiments.items() if v[0] < 0}
        neutral = {k: v for k, v in sentiments.items() if v[0] == 0}
        positive_keys = list(positive.keys())
        negative_keys = list(negative.keys())
        neutral_keys = list(neutral.keys())

        f.write(""Positive IPs:\n"")
        for ip in positive_keys:
            f.write(f""{ip}: {positive[ip][1]:.2f}, {positive[ip][0]:.6f}\n"")
        f.write(""\nNegative IPs:\n"")
        for ip in negative_keys:
            f.write(f""{ip}: {negative[ip][1]:.2f}, {negative[ip][0]:.6f}\n"")
        f.write(""\nNeutral IPs:\n"")
        for ip in neutral_keys:
            f.write(f""{ip}: {neutral[ip][1]:.2f}, {neutral[ip][0]:.6f}\n"")
    elif sys.argv[3] == ""negative"":
        positive = {k: v for k, v in sentiments.items() if v[0] > 0}
        negative = {k: v for k, v in sentiments.items() if v[0] < 0}
        neutral = {k: v for k, v in sentiments.items() if v[0] == 0}
        positive_keys = list(positive.keys())
        negative_keys = list(negative.items())
        neutral_keys = list(neutral.items())

        f.write(""Negative IPs:\n"")
        for ip, sentiment in negative:
            f.write(f""{ip}: {sentiment[1]:.2f}, {sentiment[0]:.6f}\n"")
        f.write(""\nPositive IPs:\n"")
        for ip, sentiment in positive:
            f.write(f""{ip}: {sentiment[1]:.2f}, {sentiment[0]:.6f}\n"")
        f.write(""\nNeutral IPs:\n"")
        for ip, sentiment in neutral:
            f.write(f""{ip}: {sentiment[1]:.2f}, {sentiment[0]:.6f}\n"")
    elif sys.argv[3] == ""neutral"":
        neutral = {k: v for k, v in sentiments.items() if v[0] == 0}
        positive = {k: v for k, v in sentiments.items() if v[0] > 0}
        negative = {k: v for k, v in sentiments.items() if v[0] < 0}
        neutral_keys = list(neutral.keys())
        positive_keys = list(positive.keys())
        negative_keys = list(negative.keys())

        f.write(""Neutral IPs:\n"")
        for ip in neutral_keys:
            f.write(f""{ip}: {neutral[ip][1]:.2f}, {neutral[ip][0]:.6f}\n"")
        f.write(""\nPositive IPs:\n"")
        for ip in positive_keys:
            f.write(f""{ip}: {positive[ip][1]:.2f}, {positive[ip][0]:.6f}\n"")
        f.write(""\nNegative IPs:\n"")
        for ip in negative_keys:
            f.write(f""{ip}: {negative[ip][1]:.2f}, {negative[ip][0]:.6f}\n"")
