0,"Design and implement a Python script that utilizes the Flask framework and SQLAlchemy ORM to create a database schema for managing a book lending library system. The system should include tables for users, books, and loans. Users can borrow books, return books, and view their loan history. Implement validation checks to ensure that only registered users can borrow books and that each user can only have one book checked out at a time. Return only the code for the Flask application without any additional comments or explanations.",521,,"[""```python
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from sqlalchemy import Column, Integer, String, ForeignKey, Date, Boolean
from sqlalchemy.orm import relationship

db = SQLAlchemy()

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///library.db'
db.init_app(app)

class User(db.Model):
    id = Column(Integer, primary_key=True)
    name = Column(String(50), nullable=False)
    email = Column(String(120), unique=True, nullable=False)
    loans = relationship('Loan', backref='user', lazy='dynamic')

class Book(db.Model):
    id = Column(Integer, primary_key=True)
    title = Column(String(100), nullable=False)
    author = Column(String(50), nullable=False)
    published_date = Column(Date)

class Loan(db.Model):
    id = Column(Integer, primary_key=True)
    user_id = Column(Integer, ForeignKey('user.id'), nullable=False)
    book_id = Column(Integer, ForeignKey('book.id'), nullable=False)
    borrowed_date = Column(Date, nullable=False)
    returned_date = Column(Date)
    is_checked_out = Column(Boolean, default=True)

@app.route('/register', methods=['POST'])
def register():
    user = User(name=request.json['name'], email=request.json['email'])
    db.session.add(user)
    db.session.commit()
    return jsonify({'message': 'User created'})

@app.route('/login', methods=['POST'])
def login():
    # Implement user authentication logic here and return appropriate response

@app.route('/borrow/<int:book_id>', methods=['POST'])
def borrow():
    user = User.query.filter_by(email=request.json['email']).first()
    book = Book.query.get(book_id)

    if not user or not book or user.loans.count() > 0 or book.is_checked_out:
        return jsonify({'message': 'Error borrowing book'})

    loan = Loan(user=user, book=book, borrowed_date=datetime.now())
    db.session.add(loan)
    db.session.commit()
    book.is_checked_out = True
    db.session.commit()

    return jsonify({'message': 'Book borrowed'})

@app.route('/return/<int:loan_id>')
def return_book():
    loan = Loan.query.get(loan_id)

    if not loan or not loan.is_checked_out:
        return jsonify({'message': 'Error returning book'})

    loan.returned_date = datetime.now()
    loan.is_checked_out = False
    db.session.commit()

    return jsonify({'message': 'Book returned'})

@app.route('/loans/<int:user_id>')
def get_loan_history(user_id):
    user = User.query.get(user_id)
    loans = Loan.query.filter_by(user=user).all()
    return jsonify([{
        'id': loan.id,
        'book_title': loan.book.title,
        'borrowed_date': loan.borrowed_date.strftime('%Y-%m-%d'),
        'returned_date': loan.returned_date or '',
        'is_checked_out': loan.is_checked_out
    } for loan in loans])

if __name__ == '__main__':
    app.run(debug=True)
