0,"Create a Python script that utilizes the Pandas library to read an Excel file containing a dataset of products. The dataset should include columns for product name, price, and stock quantity. The script should then process this data, calculate the total revenue based on the price and stock quantity, and export the results into a new CSV file. Implement error handling to account for cases where the Excel file is missing or contains invalid data entries.",502,,"['```python
import pandas as pd
from pathlib import Path
import csv

def read_excel(filepath):
    try:
        df = pd.read_excel(filepath, error_bad_lines=False, na_values='NA')
    except FileNotFoundError:
        print(""Excel file not found."")
        return None

    if 'product_name' not in df.columns or 'price' not in df.columns or 'stock_quantity' not in df.columns:
        print(""Invalid Excel format. Missing required columns."")
        return None

    return df

def process_data(df):
    total_revenue = df['price'] * df['stock_quantity']
    df['total_revenue'] = total_revenue
    return df

def write_csv(df, output_path):
    try:
        with open(output_path, 'w', newline='') as csvfile:
            writer = csv.DictWriter(csvfile, fieldnames=['product_name', 'price', 'stock_quantity', 'total_revenue'])
            writer.writeheader()
            for row in df.iterrows():
                writer.writerow({'product_name': row[0]['product_name'], 'price': row[0]['price'], 'stock_quantity': row[0]['stock_quantity'], 'total_revenue': row[0]['total_revenue']})
    except FileNotFoundError:
        print(""Output CSV file not found."")

if __name__ == ""__main__"":
    input_path = Path('products.xlsx')
    output_path = Path('results.csv')

    data = read_excel(input_path)

    if data is not None:
        data = process_data(data)
        write_csv(data, output_path)
```
This script reads an Excel file named 'products.xlsx' containing the required columns for product name, price, and stock quantity. It then calculates the total revenue based on these values and exports the results into a new CSV file named 'results.csv'. The code also includes error handling to handle cases where the input or output files are missing or contain invalid data entries.']",0,[0],[],True,0,0,0,

0,"Create a Python program that reads and parses a JSON file to extract specific data fields. The program should accept the file path as input and throw a custom exception if the JSON is not properly formatted or if it does not contain the required fields. Additionally, implement a function that can recursively search for nested objects within the JSON file and retrieve their values. This program should also handle cases where multiple JSON files need to be processed in a single operation, allowing for the extraction of data from each file independently.",502,,"['```python
import json
from typing import Dict, Any
import sys

class JSONParsingError(Exception):
    def __init__(self, message: str) -> None:
        super().__init__(message)

def get_value(data: Dict[str, Any], path: list[str]) -> Any:
    try:
        current = data
        for key in path:
            current = current[key]
        return current
    except (KeyError, IndexError):
        raise JSONParsingError(f""Invalid path or missing field: {path}"")

def process_json_files(file_paths: list[str]) -> None:
    for file in file_paths:
        try:
            with open(file) as f:
                data = json.load(f)
        except json.JSONDecodeError as e:
            raise JSONParsingError(f""JSON file '{file}' is not properly formatted."")

        required_fields = [""field1"", ""field2""]  # Replace with your desired field names
        if not all(field in data for field in required_fields):
            raise JSONParsingError(f""JSON file '{file}' does not contain all required fields: {required_fields}"")

        print(f""Processing JSON file '{file}':"")
        for key, value in data.items():
            if isinstance(value, dict) or isinstance(value, list):  # Check for nested objects
                print(f""\tKey: {key}"")
                print(""\tValue:"", end="" "")
                try:
                    print(get_value(data, [key]))
                except JSONParsingError as e:
                    print(e)
            else:
                print(f""\tKey: {key}\tValue: {value}"")

if __name__ == ""__main__"":
    if len(sys.argv) < 2:
        print(""Usage: python script.py file1.json [file2.json ...]"")
        sys.exit(1)

    file_paths = sys.argv[1:]
    process_json_files(file_paths)
```

This program will accept a list of JSON files as command line arguments, parse and validate them, and extract specific data fields and nested objects. To use it, save the code above to a file (e.g., `script.py`) and run it from the command line:

```sh
python script.py file1.json file2.json ...
