def min_sublist(numbers, threshold):
    start = 0
    current_sum = numbers[start]

    for index, number in enumerate(numbers[1:], start=1):
        if current_sum + number >= threshold:
            end = index
            while start < end and current_sum - numbers[start] < threshold:
                start += 1
            return numbers[start:end+1]

    return None
