        self.lock = threading.Lock()

    def enqueue(self, item):
        with self.lock:
            self.queue.append(item)

    def dequeue(self):
        with self.lock:
            if not self.is_empty():
                return self.queue.popleft()
            else:
                return None

    def is_empty(self):
        with self.lock:
            return len(self.queue) == 0

