0,"Write a Python function that accepts a string with directed graph edges (nodes separated by spaces, multiple edges by commas) as input. The function should use Kosaraju's algorithm to compute and return the number of strongly connected components in the graph. It should also print the time taken in milliseconds for the computation. Assume no self-loops or duplicate edges.",330,,"[""```python
import sys
import time
from collections import defaultdict

def kosaraju(edges):
    n = len(edges)
    graph = defaultdict(list)
    for edge in edges.split():
        graph[edge].append(int(edge.split('-')[-1]))
        graph[str(graph[edge][0]) + '-' + str(n - edge[1] - 1)].append(n - edge[0] - 1)

    order = list()
    visited = [False] * n
    stack = []

    def dfs(node):
        if not visited[node]:
            visited[node] = True
            for neighbor in graph[str(node)]:
                if not visited[neighbor]:
                    dfs(neighbor)
                    stack.append(node)

    for node in range(n):
        if not visited[node]:
            dfs(node)

    reverse_graph = defaultdict(list)
    for k, v in graph.items():
        reverse_graph[k[-1]].append(k)

    sccs = []
    for node in reversed(stack):
        visited[node] = False
        group = []
        def dfs2(node):
            if not visited[node]:
                visited[node] = True
                group.append(node)
                for neighbor in reverse_graph[str(node)]:
                    if not visited[neighbor]:
                        dfs2(neighbor)

        for node in [node]:
            if not visited[node]:
                dfs2(node)
                sccs.append(group)

    print(f'Time taken: {time.perf_counter() * 1000:.3f} ms')
    return len(sccs)

if __name__ == '__main__':
    edges = sys.argv[1]
    result = kosaraju(edges)
    print('Number of strongly connected components:', result)
```

Save this code as `strongly_connected_components.py`. Then you can run it by providing the graph edges as a command-line argument:

