0,"Design a Python script that reads and analyzes a JSON file to isolate specific data elements. The script should accept the file location as input and generate a bespoke exception if the JSON is incorrectly formatted or lacks the necessary fields. Moreover, incorporate a function capable of traversing nested objects within the JSON file to fetch their values. This application should be equipped to manage scenarios involving multiple JSON files processed simultaneously, enabling independent extraction of data from each file.",502,,"['```python
import json
import sys
from collections import defaultdict
from typing import Dict, Any

def validate_json(file):
    try:
        with open(file, 'r') as f:
            data = json.load(f)
    except FileNotFoundError:
        raise FileNotFoundError(f""File '{file}' not found."")
    except json.JSONDecodeError:
        raise ValueError(f""'{file}' is not a valid JSON file."")
    return data

def fetch_data(json_obj, keys):
    result = json_obj
    for key in keys:
        if isinstance(result, dict) and key in result:
            result = result[key]
        else:
            raise KeyError(f""Key '{key}' not found in the current object."")
    return result

def traverse_and_fetch(file, keys):
    data = validate_json(file)
    if isinstance(data, list):
        for item in data:
            yield from traverse_and_fetch(item, keys)
    else:
        try:
            yield fetch_data(data, keys)
        except KeyError as e:
            pass

def process_files(file_list):
    results = defaultdict(list)
    for file in file_list:
        try:
            for value in traverse_and_fetch(file, ['your_key']):
                results[file].append(value)
        except Exception as e:
            print(f""Error processing {file}: {str(e)}"")
    return results

if __name__ == ""__main__"":
    file_list = sys.argv[1:]
    if not file_list:
        print(""Please provide at least one JSON file path as a command-line argument."")
    else:
        result = process_files(file_list)
        for key, values in result.items():
            print(f""File '{key}': {values}"")
