```",502,,"[' ```python
import json
from typing import Any, Dict, List

class JSONParseException(Exception):
    pass

class DataExtractor:
    def __init__(self, file_path: str):
        self.file_path = file_path

    def _load_file(self) -> Dict[str, Any]:
        try:
            with open(self.file_path) as f:
                return json.load(f)
        except json.JSONDecodeError as e:
            raise JSONParseException(f""Invalid JSON format in {self.file_path}: {e}"")
        except FileNotFoundError:
            raise FileNotFoundError(f""File not found: {self.file_path}"")

    def extract_data(self) -> Dict[str, Any]:
        data = self._load_file()
        return self._search_data(data)

    def _search_data(self, obj: Any, keys: List[str]) -> Any:
        if not keys:
            return obj
        if isinstance(obj, dict):
            for key in keys[:-1]:
                obj = obj.get(key)
                if obj is None:
                    return None
            return self._search_data(obj, keys[-1:])
        elif isinstance(obj, list):
            for item in obj:
                result = self._search_data(item, keys)
                if result is not None:
                    return result
            return None
        else:
            raise ValueError(""Invalid object type to search"")

    def process_files(self, file_paths: List[str]) -> Dict[str, Any]:
        results = {}
        for file_path in file_paths:
            try:
                extracted_data = self.extract_data()
                results[file_path] = extracted_data
            except Exception as e:
                results[file_path] = str(e)
        return results
