def generate_random_packets(num_packets, packet_size_limit):
    if not isinstance(num_packets, int) or num_packets < 0:
        raise ValueError(""num_packets must be a non-negative integer"")
    if not isinstance(packet_size_limit, int) or packet_size_limit < 0:
        raise ValueError(""packet_size_limit must be a non-negative integer"")

    def random_ipv4():
        return ""."".join(str(random.randint(0, 255)) for _ in range(4))

    def hash_ipv4(ip):
        return hashlib.md5(ip.encode()).hexdigest()

    packets = []
    for _ in range(num_packets):
        dest_address = random_ipv4()
        src_address = random_ipv4()
        payload_size = random.randint(0, packet_size_limit)
        hash_dest = hash_ipv4(dest_address)
        packets.append((dest_address, src_address, payload_size, hash_dest))

    return packets

