```python
import os
from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from base64 import b64encode, b64decode

def generate_key(key_length):
    return get_random_bytes(key_length)

def encrypt_text(plaintext, key, iv):
    cipher = AES.new(key, AES.MODE_CBC, iv)
    padded_plaintext = plaintext + (AES.block_size - len(plaintext) % AES.block_size) * os.urandom(AES.block_size % len(plaintext))
    ciphertext = cipher.encrypt(padded_plaintext)
    return b64encode(ciphertext)

def decrypt_text(ciphertext_b64, key, iv):
    ciphertext = b64decode(ciphertext_b64)
    cipher = AES.new(key, AES.MODE_CBC, iv)
    decrypted_text = cipher.decrypt(ciphertext).rstrip(os.urandom(AES.block_size % len(plaintext)))
    return decrypted_text.decode()

def main():
    key_length = 32  # 256 bits key length
    while True:
        try:
            print(""1. Generate a new encryption key"")
            print(""2. Encrypt a text message"")
            print(""3. Decrypt a text message"")
            print(""0. Exit"")
            choice = int(input(""Enter your choice: ""))
            if choice == 1:
                key = generate_key(key_length)
                print(f""Generated encryption key: {b64encode(key).decode()}"")
            elif choice == 2:
                if not key:
                    print(""No encryption key available. Please generate one first."")
                    continue
                plaintext_input = input(""Enter the text to encrypt: "")
                iv_input = input(""Enter initialization vector (IV): "")
                if not iv_input or len(iv_input) != 16:
                    raise ValueError(""Invalid IV length."")
                ciphertext_b64_encoded = encrypt_text(plaintext_input.encode(), key, bytes(iv_input, 'utf-8'))
                print(f""Encrypted text: {ciphertext_b64_encoded}"")
            elif choice == 3:
                if not key:
                    print(""No encryption key available. Please generate one first."")
                    continue
                ciphertext_input_b64_encoded = input(""Enter the encrypted text to decrypt: "")
                decrypted_text_decoded_ascii_safe = decrypt_text(ciphertext_input_b64_encoded,
                                                                 bytes(key),
                                                                 bytes(iv_input,
                                                                        'utf-8'))
                print(f""Decrypted text: {decrypted_text_decoded_ascii_safe}"")
            elif choice == 0:
                break
        except Exception as e:
            print(f""Error occurred: {str(e)}"")

