0,"Create a Python script that uses command line arguments to perform a text transformation task. The script should accept options -t (to specify the type of transformation: uppercase, lowercase, or reverse), -i (to input the file path for text input), and -o (to output the file path for transformed text). If no input file is provided, it should display an error message. The help message should provide detailed usage information for each option. When an input file is given, the script should read it line by line and apply the specified transformation to each line before printing it out with its index number prefixed. Utilize standard library functions for parsing command line arguments and file handling operations.",121,,"['```python
import argparse
import sys

def transform(line, mode):
    if mode == 'upper':
        return line.upper()
    elif mode == 'lower':
        return line.lower()
    elif mode == 'reverse':
        return line[::-1]

def main():
    parser = argparse.ArgumentParser(description=""Text Transformation Script"")
    parser.add_argument(""-t"", ""--type"", required=True, help=""Type of text transformation: uppercase, lowercase or reverse."")
    parser.add_argument(""-i"", ""--input"", help=""Input file path for text input (default is stdin)"")
    parser.add_argument(""-o"", ""--output"", help=""Output file path for transformed text (default is stdout)"")

    args = parser.parse_args()

    if not args.input:
        print(""Error: No input file provided."")
        sys.exit(1)

    try:
        with open(args.input, ""r"") as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f""Error: Input file '{args.input}' not found."")
        sys.exit(1)

    transform_function = {
        'upper': transform,
        'lower': transform,
        'reverse': transform
    }[args.type]

    with open(args.output, ""w"") as f:
        for i, line in enumerate(map(transform_function, lines)):
            f.write(f""{i} {line}"")

if __name__ == ""__main__"":
    main()
```']",1,[0],[],True,0,0,0,

