def generate_device_activation_pdu(n=5):
    """"""
    Generates a list of n Device Activation PDU entities.

    Each entity contains a properly initialized SIM Information,
    IMSI, and an Activation Status Tag featuring a randomly assigned Activation Flag.

    Parameters:
    - n (int): The number of PDU entities to generate.

    Returns:
    - List[DeviceActivationPDU]: A list of generated Device Activation PDU entities.
    """"""

    def generate_sim_info():
        return {
            'serial_number': ''.join(random.choices(string.ascii_uppercase + string.digits, k=10)),
            'carrier': ''.join(random.choices(string.ascii_uppercase + string.digits, k=10))
        }

    def generate_imsi():
        return ''.join([random.choice('123456789') for _ in range(9)])

    def generate_activation_status_tag():
        activation_flag = random.choice(['Active', 'Inactive'])
        return {'activation_flag': activation_flag}

    return [DeviceActivationPDU(generate_sim_info(), generate_imsi(), generate_activation_status_tag()) for _ in range(n)]

# Example usage
