        headers = {'X-API-Key': api_key}
        response = requests.get(url, headers=headers)
        if response.status_code >= 400 and response.status_code <= 500:
            error_message = {
                400: ""Bad Request"",
                401: ""Unauthorized"",
                403: ""Forbidden"",
                404: ""Not Found"",
                500: ""Internal Server Error""
            }[response.status_code] + "": "" + response.text
