0,"Create a Python function designed to process a given text input. The function should utilize regular expressions to detect and count the frequency of words related to programming languages, ignoring case sensitivity, punctuation, and non-programming terms. The output should be a dictionary where the keys are the names of programming languages and the values represent their occurrences in the text.",185,,"[""```python
import re

def count_programming_languages(text):
    programming_regex = r'\b(python|java|javascript|c\++|c\#|ruby|php|swift|go|kotlin|rust)\b'
    non_programming_regex = r'[^\w\s]'

    words = re.findall(re.compile(programming_regex, re.IGNORECASE), text)
    filtered_words = [word for word in words if not re.search(non_programming_regex, word)]

    language_count = {}
    for word in filtered_words:
        if word in language_count:
            language_count[word] += 1
        else:
            language_count[word] = 1

    return language_count
