0,"Task: Develop a function to parse and analyze data from a JSON file. The function should extract and process details such as item IDs, prices, and stock quantities. Implement helper methods `GetNodeIntValue`, `GetNodeFloatValue`, and `Convert` to convert JSON node values into their corresponding numerical types. Finally, display the processed data after completing the configuration file analysis.",680,,"['```python
import json

def GetNodeIntValue(node):
    return int(node) if node.isdigit() else None

def GetNodeFloatValue(node):
    try:
        return float(node)
    except ValueError:
        return None

def Convert(value, target_type):
    if value is not None and isinstance(value, str):
        if target_type == int:
            return int(value)
        elif target_type == float:
            return float(value)
    return value

def AnalyzeConfigFile(file_path):
    with open(file_path, 'r') as file:
        data = json.load(file)

    items = []
    for item in data['items']:
        id_ = Convert(GetNodeIntValue(item['id']), int)
        price = Convert(GetNodeFloatValue(item['price']), float)
        quantity = Convert(GetNodeIntValue(item['quantity']), int)

        if id_, price, quantity:
            items.append({'id': id_, 'price': price, 'quantity': quantity})

    print(""Analyzed Data:"")
    for item in items:
        print(f""ID: {item['id']}, Price: {item['price']}, Quantity: {item['quantity']}"")

# Usage example
AnalyzeConfigFile('config.json')
```

