import re
from typing import Dict, Tuple

class Product:
    def __init__(self, productName: str, currency: str, amount: float, items: list = None):
        self.productName = productName
        self.currency = currency
        self.amount = amount
        self.items = items or []

class Item:
    def __init__(self, UE_INDEX: int, SIB7_CONTENT: str):
        self.UE_INDEX = UE_INDEX
        self.SIB7_CONTENT = SIB7_CONTENT

class ProductCatalog:
    def __init__(self):
        self.products = []
        self.num_products = 0

def count_programming_languages(text: str) -> Dict[str, int]:
    pattern = r'\b(javascript|java|python|c\+\+|cpp|ruby|go|swift)\b'
    matches = re.findall(pattern, text, re.IGNORECASE)
    lang_counts = {}
    for match in matches:
        match_lower = match.lower()
        if match_lower in lang_counts:
            lang_counts[match_lower] += 1
        else:
            lang_counts[match_lower] = 1
    return lang_counts

def create_product_catalog(num_products: int) -> ProductCatalog:
    catalog = ProductCatalog()
    for _ in range(num_products):
        product = create_product(3)
        catalog.products.append(product)
        catalog.num_products += 1
    return catalog

def display_product_catalog(catalog: ProductCatalog):
    for i in range(catalog.num_products):
        print(f""Product Name: {catalog.products[i].productName}"")
        print(f""Currency: {catalog.products[i].currency}"")
        print(f""Amount: {catalog.products[i].amount:.2f}"")

        print(""Items:"")

        for j in range(3):
            item_index = (i * 3) + j
            if item_index < len(catalog.products[i].items):
                print(f""UE INDEX: {catalog.products[i].items[item_index].UE_INDEX}, Content: {catalog.products[i].items[item_index].SIB7_CONTENT}"")

text_input = ""This is an example text containing terms related to several programming languages like Python, JavaScript, and Java. Let's see how many times they appear!""
programming_language_count = count_programming_languages(text_input)

product_catalog = create_product_catalog(10)
display_product_catalog(product_catalog)

print(""\nProgramming Language Counts:"")
for language, count in programming_language_count.items():
    print(f""{language}: {count}"")
