class FileParser:
    def __init__(self, filename: str):
        self.filename = filename

    def open_file(self) -> None:
        try:
            with open(self.filename, 'r') as file:
                pass
        except FileNotFoundError:
            print(f""Error: {self.filename} not found."")

    def read_line(self) -> str:
        line = None
        try:
            line = next(open(self.filename, 'r'))
        except StopIteration:
            print(f""Error: No more lines in {self.filename}"")
        return line

    def extract_numeric_field(self, line: str) -> float:
        # Implement logic to parse and extract the numeric field from a single line
        pass

class AverageCalculator:
    def __init__(self):
        self.values = []

    def add_value(self, value: float) -> None:
        self.values.append(value)

    def calculate_average(self) -> float:
        return sum(self.values) / len(self.values) if self.values else 0

def main() -> None:
    input_files = [""file1.txt"", ""file2.txt""]
    parser_instances = [FileParser(filename) for filename in input_files]
    calculator = AverageCalculator()

    for parser in parser_instances:
        parser.open_file()
        while True:
            line = parser.read_line()
            if line is None:
                break
            numeric_value = parser.extract_numeric_field(line)
            calculator.add_value(numeric_value)

    average = calculator.calculate_average()
    print(f""Average value across all files: {average}"")

if __name__ == ""__main__"":
    main()
