    def _tokenize(self, text: str) -> List[str]:
        tokenized = []
        for match in re.findall('|'.join(map(re.escape, self.patterns)), text):
            tokenized.append(match)
        return tokenized

    def _serialize(self, tokens: List[Union[str, int]]) -> str:
        return ' '.join([self.patterns[i][1] if isinstance(tokens[i], int) else tokens[i] for i in range(len(tokens))])

    def tokenize(self, text: str) -> List[Union[str, int]]:
        try:
            tokens = self._tokenize(text)
            if not tokens:
                raise ValueError('Invalid input: empty string or no matches found')
            return [self.patterns.index(pat) for pat in tokens]
        except Exception as e:
            print(f""Error: {e}"")
            return []

    def serialize(self, sequence: List[Union[str, int]]) -> str:
        return self._serialize(sequence)

